"""Render completed R61 scorecard; does not run measurements or change Git."""
from pathlib import Path
import json,sys
s=json.loads(Path(sys.argv[1]).read_text());out=Path(sys.argv[2]);p=s['primary'];ref=p['reference_seconds'];before=p['medians']['before'];after=p['medians']['after'];comparison=p['comparisons']['after_over_before']
lines=['# R61: numeric first-change scalar transport','',f"Candidate compiler: `{s['static']['after']['source']}`. Baseline R60 compiler: `{s['static']['before']['source']}`. Only GPU was rebuilt; every other production library hash, feature set and profile is unchanged.",'',f"The complete eight-byte level-12 call measured **{after['multiple_of_reference']:.6f}× the reference**, from **{before['multiple_of_reference']:.6f}×** in the matched baseline cohort. Candidate/baseline elapsed is **{comparison['pooled_ratio']:.8f}×** ({s['changes_percent']['primary_seconds']:+.4f}%). Reference median: {ref*1000:.6f} ms.",'','The candidate removes the redundant scalar spill in numeric_boundary materialization. Current scalar carrier fields, source index, incoming word and finite fuel are transported explicitly through the existing argument lane. Other live arithmetic values remain in SSA with normal backend call-clobber preservation. The helper has no pointer to the generated local bank, and that omitted whole-bank snapshot has no reader on this boundary. Ready-flag, origin, capacity, failure and recovery handling remains in place; ordinary bailout and successful-exit spills remain unchanged. This changes emitted stores, not the compressor algorithm, allocation behavior or logical resource charges. R60 remains the explicit baseline despite its measured elapsed tradeoff: its previous instruction reduction is not claimed as a latency reduction.','', '| Metric | Reference | R60 baseline | R61 candidate | Change |','|---|---:|---:|---:|---:|',f"| Primary elapsed (ms) | {ref*1000:.6f} | {before['seconds']*1000:.6f} | {after['seconds']*1000:.6f} | {s['changes_percent']['primary_seconds']:+.4f}% |"]
for section,key,label in [('cpu','instructions','Retired instructions'),('cpu','cycles','CPU cycles'),('allocation','allocation_requests','Allocation requests'),('allocation','requested_bytes','Requested bytes'),('allocation','reallocations','Reallocations'),('allocation','peak_live_usable','Peak allocator live usable bytes'),('allocation','incremental_peak_live_usable','Incremental peak live usable bytes'),('cpu','rss_after','RSS after call'),('cpu','physical_after','Physical footprint after call')]:
 values=[s[section][variant][key]['median'] for variant in ['reference','before','after']];change=s['changes_percent'][key];lines.append('| '+label+' | '+' | '.join(f'{v:,.1f}' if int(v)!=v else f'{v:,.0f}' for v in values)+' | '+('—' if change is None else f'{change:+.4f}%')+' |')
diagnostic=s['diagnostic_cpu_elapsed']
lines+=['',f"The separate CPU-counter cohort elapsed is {diagnostic['before']['median_seconds']*1000:.6f} → {diagnostic['after']['median_seconds']*1000:.6f} ms ({diagnostic['change_percent']:+.6f}%). All 32 observations per variant are excluded from primary elapsed. This contrary diagnostic elapsed is retained independently of the matched primary result."]
lines+=['','Primary elapsed, CPU counters, allocation counters and sampling are separate serialized cohorts. Their percentages are not multiplied or combined into a synthetic result. Requested bytes measure allocation requests, not initialized bytes copied. Allocator peak and post-call OS footprint are distinct measures; retained compiler/catalog/image storage is included.','', '## Matched pairs and contrary observations','', '| Pair | Baseline ms | Candidate ms | Candidate/baseline |','|---|---:|---:|---:|']
for group in p['groups']:lines.append(f"| {group['group']} | {group['medians']['before']*1000:.6f} | {group['medians']['after']*1000:.6f} | {group['after_over_before']:.8f}× |")
lines+=['',f"{comparison['improving_groups']}/4 independently prepared pairs and {comparison['improving_blocks']}/64 alternating blocks improve. Each pair has 16 blocks ×31 measured calls per variant: 3,968 total primary observations. Individual blocks within a prepared pair are descriptive, not independent experiments.",'', 'Counter directions that increased are retained below; an empty object means no listed median increased:','', '```json',json.dumps(s['contrary_counter_directions'],indent=2),'```','', '## Generated binary','', '| Metric | R60 baseline | R61 candidate |','|---|---:|---:|']
for key,label in [('code_bytes','Generated text bytes'),('stack_bytes','Machine entry stack bytes'),('typed_ir_version','Typed IR version'),('abi_version','ABI version')]:lines.append(f"| {label} | {s['static']['before'][key]:,} | {s['static']['after'][key]:,} |")
audit=s['binary_audit'];stores=sum(audit['opcode_delta'].get(name,0) for name in ['str','stur','strb']);stack_stores=audit['stack_accesses']['total']['stack_store']['delta']
lines+=['',f"The actual Objects contain {-stores:,} fewer scalar store instructions: {-stack_stores:,} fewer machine-stack stores and {-(stores-stack_stores):,} fewer other stores. Static scalar stack loads decrease by {-audit['stack_accesses']['total']['stack_load']['delta']:,}. UDIV remains {audit['UDIV']['before']} → {audit['UDIV']['after']}. These are encoded instruction counts, not dynamic visits or the retired-instruction saving. Generated text falls by {-audit['code_bytes']['delta']:,} bytes and entry stack by {-audit['stack_bytes']['delta']:,} bytes."]
lines+=['','The candidate Object is independently bound to its corresponding image and libraries. Equality with the baseline Object is not an acceptance requirement. Actual binary audit:','','```json',json.dumps(s['binary_audit'],indent=2),'```','', '## Correctness and unchanged workload','', 'The input is eight bytes `abcdefgh`; exact raw output remains `[75,76,74,78,73,77,75,207,0,0]`, with independent inflation. Output capacity remains 13 and is cleared/reused. The tree contains 262,144 U16 entries, the cache 1,500,513 U32 words, search depth is 300 and nice length 258. Input aliases, finite admission/error order, previous publication on failure and recovery remain covered. Logical work is 60,260,219,686 and comparison work 47,612; neither is a hardware instruction count. Final managed bytes and nodes remain zero.','', 'The source and bytecode are unchanged:','','```json',json.dumps(s['source_pins'],indent=2),'```','', '## Qualification','',f"Qualification status: **{s['validation'].get('status', 'passed' if s['validation']['all_required_checks_pass'] else 'failed')}**. Exact counts come from archived inventories and executed receipts. Batches overlap; they are not a sum of unique tests.",'', '| Receipt | Expected tests | Observed | Passed |','|---|---:|---:|---|']
for row in s['validation']['checks']:
 if row.get('inventory_only'):continue
 lines.append(f"| `{row['receipt']}` | {row.get('expected_tests','—')} | {row.get('observed_tests',row.get('cases','—'))} | {row['passed']} |")
lines+=['','Skipped coverage:']
for row in s['validation']['skipped_coverage']:lines.append('- '+row.get('test',row.get('coverage'))+': '+row['disposition'])
lines+=['','Retained earlier failed attempts:']
for row in s['validation'].get('prior_failures',[]):lines.append('- '+row['receipt']+': '+row['disposition'])
lines+=['','Decision: '+s['decision']['status']+'. '+s['decision']['reason']]
lines+=['','## Replay','', 'Run `python3 reconstruct.py /new/empty/output/path` from this evidence packet. It verifies every archived receipt version, overlays versions chronologically and reproduces scorecard, profile and validation JSON. No compiler, compressor executable or performance rerun is required.','', 'This is a small-input complete-compression result. It does not establish larger-input throughput or a standalone minimum memory footprint. All directions and the retain/reject decision come from the observed R61 receipts and explicit decision record. No percentages from earlier rounds are combined into this result.','']
confirmation=json.loads((Path(sys.argv[1]).parent.parent/'confirmation-scorecard.json').read_text());cp=confirmation['primary'];cb=cp['medians']['before'];ca=cp['medians']['after'];cc=cp['comparisons']['after_over_before']
lines+=['','## Separate final confirmation: R56 to R61','',f"A fresh elapsed-only comparison of the accepted starting R56 executable and final R61 executable measured **{cb['multiple_of_reference']:.6f}× → {ca['multiple_of_reference']:.6f}×** the shared reference ({cb['seconds']*1000:.7f} → {ca['seconds']*1000:.7f} ms; {confirmation['change_percent']:+.6f}%). {cc['improving_groups']}/4 prepared pairs and {cc['improving_blocks']}/64 blocks improve. This is a separate 3,968-observation cohort with its own {cp['reference_seconds']*1000:.6f} ms reference; no earlier percentage is multiplied into it.",'', '| Pair | R56 ms | R61 ms | Change |','|---|---:|---:|---:|']
for group in cp['groups']:lines.append(f"| {group['group']} | {group['medians']['before']*1000:.7f} | {group['medians']['after']*1000:.7f} | {100*(group['after_over_before']-1):+.6f}% |")
lines+=['','The adverse fourth pair is retained. This confirmation establishes no additional instruction, cycle, allocation or peak-memory result; those remain the separate per-change cohorts. `confirm.py` recomputes every timed row and all 64 block medians, verifies the two frozen worker bindings and reproduces `confirmation-scorecard.json` as the fifth replay output.','']
out.write_text('\n'.join(lines))
